svg.script:
(function(){
  var svg = document.documentElement;
  svg.setAttribute('tabindex','0');
  function qsa(sel){ return Array.from(svg.querySelectorAll(sel)); }
  function byClass(c){ return qsa('.' + CSS.escape(c)); }
  var edges = Array.from(svg.querySelectorAll('g.edge'));
  edges.forEach(function(e){
    var from = e.getAttribute('data_from') || e.getAttribute('data-from') || (e.dataset && (e.dataset.from || e.dataset.data_from));
    var to   = e.getAttribute('data_to')   || e.getAttribute('data-to')   || (e.dataset && (e.dataset.to   || e.dataset.data_to));
    if (!from || !to){
      var id = e.getAttribute('id') || '';
      var m = /^edge__(.+?)__(.+)$/.exec(id);
      if (m){ from = from || m[1]; to = to || m[2]; }
    }
    if (from) e.classList.add('from__' + from);
    if (to)   e.classList.add('to__'   + to  );
  });
  var selectedNodeId = null;
  function clearHighlights(){
    svg.classList.remove('highlight-mode');
    qsa('.highlight,.outgoing,.incoming').forEach(function(el){
      el.classList.remove('highlight','outgoing','incoming');
    });
  }
  function highlightNode(nodeId){
    clearHighlights();
    selectedNodeId = nodeId;
    svg.classList.add('highlight-mode');
    var node = svg.getElementById(nodeId);
    if (node) node.classList.add('highlight');
    byClass('from__' + nodeId).forEach(function(e){ e.classList.add('outgoing'); });
    byClass('to__'   + nodeId).forEach(function(e){ e.classList.add('incoming'); });
  }
  function setMuted(nodeId, muted){
    var n = svg.getElementById(nodeId);
    if (n) n.classList.toggle('muted', muted);
    byClass('from__' + nodeId).forEach(function(e){ e.classList.toggle('muted', muted); });
    byClass('to__'   + nodeId).forEach(function(e){ e.classList.toggle('muted', muted); });
  }
  function isMuted(nodeId){
    var n = svg.getElementById(nodeId);
    return !!(n && n.classList.contains('muted'));
  }
  qsa('g.node[id]').forEach(function(g){
    var id = g.getAttribute('id'); if (!id) return;
    g.addEventListener('click', function(ev){ ev.stopPropagation(); highlightNode(id); });
  });
  svg.addEventListener('click', function(){ clearHighlights(); selectedNodeId = null; });
  window.addEventListener('keydown', function(ev){
    if (ev.key === 'Escape'){ clearHighlights(); selectedNodeId = null; return; }
    if ((ev.key === 'h' || ev.key === 'H') && selectedNodeId){
      ev.preventDefault();
      setMuted(selectedNodeId, !isMuted(selectedNodeId));
    }
    if (ev.key === 'u' || ev.key === 'U'){
      qsa('.muted').forEach(function(el){ el.classList.remove('muted'); });
    }
  });
})();
